import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import styles from "./AppStyles.module.css"; 
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle.min";

function App() {
  const [userName, setUserName] = useState("");
  const [pwd, setPwd] = useState("");
  const navigate = useNavigate();
  const [value, setValue] = useState("");
  const [isLoginActive, setIsLoginActive] = useState(true); // State to toggle between login and register forms



  const update = (e) => {
    e.preventDefault();
    if (userName === "admin" && pwd === "admin123") {
        alert("Login Success");
        navigate("/header");
    } else {
        alert("Login Failed");
    }
  };

  const toggleForms = (formType) => {
    setIsLoginActive(formType === "login");
  };

  return (
    <div className={styles.parent_container}>
      <div className={`${styles.form_container} ${isLoginActive ? "" : styles.register_active}`}>
        <div className={styles.col}>
          <div className={styles.btn_box}>
            <button
              className={styles.btn}
              onClick={() => toggleForms("login")}
            >
              Sign In
            </button>
            <button
              className={styles.btn}
              onClick={() => toggleForms("register")}
            >
              Sign Up
            </button>
          </div>
        </div>
        <div className={styles.container}>
          <form onSubmit={update}>
            {/* Login Form */}
            {isLoginActive ? (
              <div className={styles.login_form}>
                <div className={styles.form_title}>
                  <span>Sign In</span>
                </div>
                <div className={styles.form_inputs}>
                  <div className={styles.input_box}>
                    <input
                      type="text"
                      className={styles.input_field}
                      onChange={(e) => setUserName(e.target.value)}
                      placeholder="Username"
                      required
                    />
                  </div>
                  <div className={styles.input_box}>
                    <input
                      type="password"
                      className={styles.input_field}
                      onChange={(e) => setPwd(e.target.value)}
                      placeholder="Password"
                      required
                    />
                  </div>
                  <div className={styles.forget_pass}>
                    <a href="/recover-password">Forget Password</a>
                  </div>
                  <div className={styles.input_box}>
                    <button className={styles.input_submit}>
                      <span>Sign In</span>
                    </button>
                  </div>
                </div>
              </div>
            ) : (
              // Register Form
              <div className={styles.register_form}>
                <div className={styles.form_title}>
                  <span>Create Account</span>
                </div>
                <div className={styles.form_inputs}>
                  <div className={styles.input_box}>
                    <input
                      type="email"
                      className={styles.input_field}
                      placeholder="Email"
                      required
                    />
                  </div>
                  <div className={styles.input_box}>
                    <input
                      type="text"
                      className={styles.input_field}
                      placeholder="Username"
                      required
                    />
                  </div>
                  <div className={styles.input_box}>
                    <input
                      type="password"
                      className={styles.input_field}
                      placeholder="Password"
                      required
                    />
                  </div>
                  <div className={styles.input_box}>
                    <button className={styles.input_submit}>
                      <span>Sign Up</span>
                    </button>
                  </div>
                </div>
              </div>
            )}
          </form>
        </div>
      </div>
    </div>
  );
}

export default App;
